const webhookInput = $input.first().json;
const body = webhookInput.body || webhookInput;
const itemId = body.objectId || body.id;

if (!itemId) {
  return [{ json: { error: 'Missing itemId', received: body } }];
}

return [{ json: { itemId: String(itemId) } }];

const response = $input.first().json;
const results = response.results || [];

if (results.length === 0) {
  return [{ json: { error: 'No associated ticket found' } }];
}

const ticketId = results[0].id;
return [{ json: { ticketId } }];

const items = $input.first().json.results || [];
if (items.length === 0) { return [{ json: { error: 'No associated items' } }]; }
const STAGE_ORDER = { '1386096010':0, '1388087301':1, '1388087302':2, '1386096011':3 };
let lowestStage=null, lowestRank=Infinity; const stages=[];
for (const item of items){ const st=String(item.properties.hs_pipeline_stage); stages.push(st); const r=STAGE_ORDER[st]; if(r!==undefined && r<lowestRank){lowestRank=r; lowestStage=st;} }
if (lowestStage===null){ return [{ json:{ error:'No recognized item stages', stages } }]; }
const _OWNER={grant:'90350604',jessica:'583682960',barbara:'967443664'};
const _GRANT=['Shortage','Wrong Substitution','Mispick']; const _JESSICA=['Incorrect Price','Order Error'];
const _itemOwnerFn=(stage,ct)=>{ if(stage==='1386096011')return null; if(stage==='1388087301')return _OWNER.jessica; if(_GRANT.includes(ct))return _OWNER.grant; if(_JESSICA.includes(ct))return _OWNER.jessica; return _OWNER.barbara; };
const _ticketOwnerFn=(s)=>{ if(s==='1386096010')return _OWNER.barbara; if(s==='1388087301')return _OWNER.jessica; if(s==='1388087302')return _OWNER.barbara; return null; };
const triggerId = String($('Extract Item Info').first().json.itemId || '');
const trig = items.find(i=>String(i.id)===triggerId);
let triggerItemOwner=null;
if (trig){ triggerItemOwner=_itemOwnerFn(String(trig.properties.hs_pipeline_stage), trig.properties.complaint_type||''); }
const ticketOwner=_ticketOwnerFn(lowestStage);
return [{ json: { itemStage: lowestStage, triggerItemId: triggerId, triggerItemOwner, ticketOwner, allStages: stages, itemCount: items.length, success: true } }];

const itemStage = $json.itemStage;
const stageMapping = { '1386096010':'1385996039','1388087301':'1387983013','1388087302':'1387983014','1386096011':'1385996040' };
const ticketStage = stageMapping[itemStage];
if (!ticketStage){ return [{ json:{ error:'No ticket stage mapping for item stage: '+itemStage } }]; }
return [{ json: { ticketStage, itemStage, ticketOwner: $json.ticketOwner || null } }];
